  // Surface tiles use the same irregular basin brush as the debug `dig`
  // command.  The tile remains the liquid at the bottom; this only supplies
  // the visual cut and keeps contiguous pools from reading as flat squares.
  for (const region of surfaceRegions) {
    for (const cell of region?.cells || []) {
      const cx = Number(cell?.x);
      const cy = Number(cell?.y);
      if (!Number.isFinite(cx) || !Number.isFinite(cy)) continue;
      const radius = 0.62;
      const seed = Number.isFinite(region?.seed) ? (region.seed | 0) : 0;
      const maxR = radius * 1.21;
      const sx0 = Math.floor((cx - maxR - tx0 + 0.5) * SUB);
      const sy0 = Math.floor((cy - maxR - ty0 + 0.5) * SUB);
      const sx1 = Math.ceil((cx + maxR - tx0 + 0.5) * SUB);
      const sy1 = Math.ceil((cy + maxR - ty0 + 0.5) * SUB);
      const mx0 = Math.max(0, sx0);
      const my0 = Math.max(0, sy0);
      const mx1 = Math.min(w - 1, sx1);
      const my1 = Math.min(h - 1, sy1);
      for (let sy = my0; sy <= my1; sy++) {
        const wy = ty0 - 0.5 + (sy + 0.5) * INV_SUB;
        const rowOff = sy * w;
        for (let sx = mx0; sx <= mx1; sx++) {
          const wx = tx0 - 0.5 + (sx + 0.5) * INV_SUB;
          const dx = wx - cx;
          const dy = wy - cy;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist > maxR) continue;
          const ang = Math.atan2(dy, dx);
          const sector = Math.floor(((ang + Math.PI) / (Math.PI * 2)) * 24);
          const wobble = ((hash2i(sector, seed, 0x7f4a7c15 ^ seed) * 2) - 1) * 0.75
            + Math.sin(ang * 3 + seed * 0.013) * 0.1375
            + Math.sin(ang * 5 + seed * 0.021) * 0.1125;
          const effR = Math.max(radius * 0.25, radius * (1 + 0.22 * wobble));
          if (dist > effR) continue;
          const t = Math.max(0, 1 - dist / effR);
          const k = Math.pow(t, 1.3) * (1 + 0.10 * ((valueNoise2(wx * 2.1, wy * 2.1, 0x5bd1e995 ^ seed) * 2) - 1));
          floorH[rowOff + sx] -= 0.5 * k;
        }
      }
    }
  }

  floorGX.fill(0);
  floorGY.fill(0);
  for (let sy = 1; sy < h - 1; sy++) {
    const rowOff = sy * w;
    for (let sx = 1; sx < w - 1; sx++) {
      const i = rowOff + sx;
      floorGX[i] = (floorH[i + 1] - floorH[i - 1]) * 0.5;
      floorGY[i] = (floorH[i + w] - floorH[i - w]) * 0.5;
    }
  }
